from time import sleep

from .message_handling import (Structure, Query, BasicQueryManager,
                               u8, u16, u32)
from .msg_service import ServiceInterface
from .msg_cell_list import CellListInterface
from .msg_channel_list import ChannelListInterface
from .msg_general_report import (BrowserStartGeneralReportReq, BrowserStartGeneralReportResp,
                                 BrowserStopGeneralReportReq, BrowserStopGeneralReportResp,
                                 BrowserGeneralReportInd, BrowserGeneralReportIndSink)

from ..collectors import BaseTraceCollector
from ..commons import LOGGER, TRACE_STORE
from ..utils import get_context_id, get_procedure_id


from .sack_reflection_interface import EBrowserObjectName, EBrowserReportType, get_browser_object_name

MAX_NUM_OF_RX_ANTENNAS_IN_LOCAL_CELL = 4


class StartStreamInfo(Query):
    def __init__(self, req, resp):
        super(StartStreamInfo, self).__init__(req, resp)

    def fill_req_msg(self, report_name, meas_period, cell_id):
        # type: (int, int, int) -> None
        self.req_msg.contextId = (get_context_id() << 16) | (report_name & 0xffff)
        self.req_msg.procedureId = get_procedure_id()

        self.req_msg.reportName = report_name
        self.req_msg.reportPeriod = meas_period

        self.req_msg.priority = 0
        self.req_msg.reportType = EBrowserReportType.EBrowserReportType_PeriodicCollected
        self.req_msg.startSfn = 0xFFFFFFFF  # SPPE_UNSYNC_SFN
        self.req_msg.reportingDuration = 0
        self.req_msg.reportGranularityScale = 1
        self.req_msg.granularity = 1
        self.req_msg.decimationFactor = 1
        self.req_msg.threshold1 = 0
        self.req_msg.threshold2 = 0
        self.req_msg.timeScale = 0
        self.req_msg.time1 = 0
        self.req_msg.time2 = 0

        self.req_msg.numberOfAssociatedObjects = 1
        self.req_msg.dynamicData[0] = EBrowserObjectName.EBrowserObjectName_Cell
        self.req_msg.dynamicData[1] = cell_id

    def _handle_response(self):
        # type: () -> None
        status = self.resp_msg.status
        if status != 0:
            LOGGER.warning('Trace collection start error (BrowserStartGeneralReportResp with status {})'.format(status))


class StopStartStreamInfo(Query):
    def __init__(self, req, resp):
        super(StopStartStreamInfo, self).__init__(req, resp)

    def fill_req_msg(self, report_name, context_id, procedure_id):
        # type: (int, int, int) -> None
        self.req_msg.contextId = context_id
        self.req_msg.procedureId = procedure_id
        self.req_msg.reportName = report_name

    def _handle_response(self):
        # type: () -> None
        status = self.resp_msg.status
        if status != 0:
            LOGGER.warning('Trace collection stop error (BrowserStopGeneralReportResp with status {}) '.format(status))


class StreamInfo(Structure):
    _fields_ = [
        ('origStreamPwr', u32 * MAX_NUM_OF_RX_ANTENNAS_IN_LOCAL_CELL),
        ('picDelayedStreamPwr', u32 * MAX_NUM_OF_RX_ANTENNAS_IN_LOCAL_CELL),
        ('tir', u16 * MAX_NUM_OF_RX_ANTENNAS_IN_LOCAL_CELL),
        ('picDelayedStreamStatus', u8 * MAX_NUM_OF_RX_ANTENNAS_IN_LOCAL_CELL)
    ]


class RakeStreamInfoCollector(BaseTraceCollector):
    def __init__(self, connection):
        super(RakeStreamInfoCollector, self).__init__(connection)
        self.cell_id = None  # type: int

        self.report_name = EBrowserObjectName.EBrowserObjectName_RakeStreamInfo
        self.trace_name = get_browser_object_name(self.report_name)

    def prepare_query_managers(self):
        if not self.board:
            return
        board, cpu = self.board, self.cpu
        start_query = StartStreamInfo(BrowserStartGeneralReportReq(board, cpu), BrowserStartGeneralReportResp())
        start_query.fill_req_msg(self.report_name, self.meas_period, self.cell_id)

        context_id, procedure_id = start_query.req_msg.contextId, start_query.req_msg.procedureId

        stop_query = StopStartStreamInfo(BrowserStopGeneralReportReq(board, cpu), BrowserStopGeneralReportResp())
        stop_query.fill_req_msg(self.report_name, context_id, procedure_id)

        self.start_qm = BasicQueryManager(start_query, self.connection)
        self.stop_qm = BasicQueryManager(stop_query, self.connection)
        self.ind_m = BrowserGeneralReportIndSink(cookie=(BrowserGeneralReportInd.id, context_id, procedure_id))

    def find_target_board_cpu(self, cell_id):

        candidate_board_and_cpu_ids = ServiceInterface(self.connection).get_board_cpu_pairs_with_given_service_or_message(
            self.report_name)

        target_board, target_cpu = None, None
        for board, cpu in candidate_board_and_cpu_ids:
            trial_cell_ids = CellListInterface(self.connection).get_cell_ids(board, cpu)
            channel_list = ChannelListInterface(self.connection).get_cell_channel_list(board, cpu, cell_id)
            if cell_id in trial_cell_ids and channel_list:
                target_board, target_cpu = board, cpu
                break

        if not target_cpu:
            LOGGER.warning(
                'Could not determine board and cpu for getting Rake Stream Info for cell {}'.format(cell_id)
            )
            return

        self.board = target_board
        self.cpu = target_cpu

        LOGGER.info('{} will be collected from 0x{:x}{:x}'.format(self.trace_name, self.board, self.cpu))


def _collect_rake_stream_info(cell_id, trace_time, output_path, trace_alias, connection):
    # type: (int, int, str, str, ...) -> None

    collector = _prepare_rake_stream_info_collector(cell_id, connection)
    if collector:
        TRACE_STORE.add(collector, trace_alias)

        collector.start()
        sleep(trace_time)
        collector.stop()
        collector.save_traces(output_path)


def _prepare_rake_stream_info_collector(cell_id, connection):
    meas_period = 100  # ms

    collector = RakeStreamInfoCollector(connection)
    collector.set_parameters(
        cell_id=cell_id,
        meas_period=meas_period
    )
    collector.find_target_board_cpu(cell_id)
    collector.prepare_query_managers()
    return collector
